"use client";
import { ArtemisScope } from "./artemis-scope";
import View1 from "./components/image-galleries/variants/02-morphing-mosaic";
const variants = {"morphing-mosaic":View1};
export interface ArtemisImageGalleriesProps { className?: string; variant?: "morphing-mosaic"; }
export function ArtemisImageGalleries({ className, variant = "morphing-mosaic" }: ArtemisImageGalleriesProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useRef, useState } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_SPRING_LAYOUT } from "../../../lib/ease";
import { MOSAIC_ITEMS } from "./02-morphing-mosaic/items";
const imageClass = "art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:inline-block art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:group art:relative art:cursor-pointer art:overflow-hidden art:bg-muted art:text-left art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
const numberClass = "art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:inline-block art:p-0 art:font-normal art:h-10 art:min-w-10 art:border art:border-border art:px-3 art:font-mono art:text-xs art:tabular-nums art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
export default function ImageGalleriesMorphingMosaic() {
    const [active, setActive] = useState(0);
    const sectionRef = useRef<HTMLElement>(null);
    const visible = useInView(sectionRef, { margin: "120px" });
    const reducedMotion = useReducedMotion() ?? false;
    useEffect(() => {
        if (!visible || reducedMotion)
            return;
        const timer = window.setInterval(() => setActive((current) => (current + 1) % MOSAIC_ITEMS.length), 4600);
        return () => window.clearInterval(timer);
    }, [visible, reducedMotion]);
    return (<section ref={sectionRef} className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
          <header className="art:mx-auto art:max-w-3xl art:text-center">
            <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.16em]">
              {"Living collection"}
            </p>
            <h2 className="art:mt-5 art:text-balance art:font-medium art:text-4xl art:leading-[1.02] art:tracking-[-0.045em]">
              <span className="art:block">
                {"Every frame gets"}
              </span>
              <span className="art:block">
                {"its moment"}
              </span>
            </h2>
            <p className="art:mx-auto art:mt-5 art:max-w-xl art:text-pretty art:text-muted-foreground art:leading-7">
              {"A shifting editorial mosaic that reshapes itself around the selected image"}
            </p>
          </header>
        <div className="art:mt-10 art:grid art:h-[36rem] art:grid-cols-2 art:grid-rows-4 art:gap-2 art:border-border art:border-y art:py-2 art:@min-[640px]/artemis:gap-3 art:@min-[640px]/artemis:py-3 art:@min-[1024px]/artemis:h-[40rem] art:@min-[1024px]/artemis:grid-cols-12 art:@min-[1024px]/artemis:grid-rows-2">
          {MOSAIC_ITEMS.map((item, index) => {
            const selected = index === active;
            return (<ArtemisButton key={item.title} variant="link" size="none" className={`${imageClass} ${selected ? "art:col-span-2 art:row-span-2 art:@min-[1024px]/artemis:col-span-6 art:@min-[1024px]/artemis:row-span-2" : "art:col-span-1 art:row-span-1 art:@min-[1024px]/artemis:col-span-3 art:@min-[1024px]/artemis:row-span-1"}`} aria-label={`Focus ${item.title}`} aria-pressed={selected} style={{ order: (index - active + MOSAIC_ITEMS.length) % MOSAIC_ITEMS.length }} layout transition={reducedMotion ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT} onClick={() => setActive(index)}>
                <motion.img src={item.src} alt={item.alt} width={1200} height={1600} loading="lazy" className="art:h-full art:w-full art:object-cover" animate={{ scale: reducedMotion ? 1 : selected ? 1.01 : 1.07, opacity: selected ? 1 : 0.82 }} transition={reducedMotion ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>
                {selected && (<motion.span className="art:absolute art:right-3 art:bottom-3 art:left-3 art:flex art:items-end art:justify-between art:gap-4 art:bg-background/80 art:p-4 art:text-foreground art:backdrop-blur-md art:@min-[640px]/artemis:p-5" initial={reducedMotion ? false : { opacity: 0, y: 12, filter: "blur(8px)" }} animate={{ opacity: 1, y: 0, filter: "blur(0px)" }} transition={reducedMotion ? { duration: 0 } : { duration: 0.42, delay: 0.14, ease: "easeOut" }}>
                    <span className="art:font-medium">{item.title}</span>
                    <span className="art:text-muted-foreground art:text-xs">{item.caption}</span>
                  </motion.span>)}
              </ArtemisButton>);
        })}
        </div>
        <fieldset className="art:mt-5 art:flex art:justify-center art:gap-2">
          <legend className="art:sr-only">{"Choose an image"}</legend>
          {MOSAIC_ITEMS.map((item, index) => (<ArtemisButton key={item.title} variant="link" size="none" className={`${numberClass} ${active === index ? "art:hover:bg-transparent art:hover:text-inherit art:bg-foreground art:text-background" : "art:bg-background art:text-muted-foreground art:hover:bg-muted art:hover:text-foreground"}`} aria-label={`Show ${item.title}`} aria-pressed={active === index} onClick={() => setActive(index)}>
              {String(index + 1).padStart(2, "0")}
            </ArtemisButton>))}
        </fieldset>
      </div>
    </section>);
}

// @zeus-internal
export const MOSAIC_ITEMS = [
    {
        title: "Coastal house",
        caption: "Morning light",
        src: "/assets/artemis/00f08a1b00c26bee6c90.avif",
        alt: "Sunlit living room overlooking the coast",
    },
    {
        title: "Stone study",
        caption: "Material archive",
        src: "/assets/artemis/2ce5b4a2815dab6dd072.avif",
        alt: "Sculptural stone interior detail",
    },
    {
        title: "The long room",
        caption: "Working studio",
        src: "/assets/artemis/0fa3094a5a49b43eda46.avif",
        alt: "Quiet creative studio with long worktables",
    },
    {
        title: "Inner court",
        caption: "Late afternoon",
        src: "/assets/artemis/e9310d36bf6a9fb11295.avif",
        alt: "Warm modern courtyard framed by timber",
    },
    {
        title: "White gallery",
        caption: "Natural light",
        src: "/assets/artemis/d2a1ef4851ad61ca357c.avif",
        alt: "Minimal gallery room washed in natural light",
    },
] as const;
